INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('hilliard-2026-cardiac-monitoring', 'Aligning Cardiac Monitoring with American Heart Association Guidelines: Impact on Utilization, Hemodynamic Monitoring, and Outcomes', 'Hilliard B, Mehta T, Grace J, Pestka DL, Ingraham NE, Beebe T, Tignanelli C, Melton GB, Shippee N, Koopmeiners JS, Usher M.', 'PLoS One', 2026, 'Published', 'https://doi.org/10.1371/journal.pone.0338943', 'https://pubmed.ncbi.nlm.nih.gov/41616031/', NULL, '["quality"]', 0, '["nick"]');
