INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('olson-2026-pccm-job-offers', 'Variability in First Academic Medicine Job Offers in Pulmonary and Critical Care Medicine', 'Olson EM, Modes ME, Rowe TJ, Lyons PG, Ingraham NE, Nadig NR, Schroedl CJ, Gao CA.', 'ATS Scholar', 2026, 'Published', 'https://doi.org/10.1093/atsscholar/aapag010', 'https://pubmed.ncbi.nlm.nih.gov/41734005/', NULL, '["quality"]', 0, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('ingraham-2026-adhere-lpv', 'Advancing Delivery of High-Quality Evidence-Based Respiratory Efforts in Lung-Protective Ventilation (ADHERE-LPV): A Cluster-Randomized Controlled Trial Study Protocol', 'Ingraham NE, Potter J, Botsford C, Johnson T, Eddington C, Mesfin N, Kaur M, Hager N, Lindemann E, Beebe TJ.', 'In preparation', 2026, 'In Preparation', NULL, NULL, 'Protocol for a cluster-randomized controlled trial testing a precision practice assistance intervention to improve lung-protective ventilation adherence in the ICU.', '["ventilation","quality"]', 0, '["nick","nate"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('ingraham-2026-gdms-lpv', 'Association of General Decision-Making Style with Lung-Protective Ventilation Adherence', 'Ingraham NE, Bromley E, Eddington C, Collins C, Dudley RA, Chipman JG.', 'In preparation', 2026, 'In Preparation', NULL, NULL, 'This study examines the relationship between physicians'' general decision-making styles, measured by the GDMS instrument, and their adherence to lung-protective ventilation protocols in the ICU. By linking survey data with clinical EHR data across multiple centers, we characterize how rational, intuitive, dependent, avoidant, and spontaneous decision-making styles predict evidence-based practice adherence.', '["decision-making","ventilation"]', 0, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('mesfin-2026-dnr', 'DNR Order Variation Across Providers', 'Mesfin N, Ingraham NE, et al.', 'In preparation', 2026, 'In Preparation', NULL, NULL, 'Characterizing provider-level variation in DNR order documentation patterns and their association with patient outcomes and goals-of-care conversations.', '["decision-making"]', 0, '["nate"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('mesfin-2026-ihca', 'In-Hospital Cardiac Arrest Survivability', 'Mesfin N, et al.', 'In preparation', 2026, 'In Preparation', NULL, NULL, 'A predictive modeling study examining factors that influence survivability after in-hospital cardiac arrest, with the goal of improving prognostication and clinical decision-making.', '["decision-making"]', 0, '["nate"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('shyu-2025-peripheral-vasopressors', 'Overview of Peripheral Vasopressor Use in an Academic Health System', 'Shyu D, Ingraham NE, Linke CA, Siegel L, Larson JA, Benson AR, Pendleton KM.', 'Annals of the American Thoracic Society', 2025, 'Published', 'https://doi.org/10.1513/AnnalsATS.202411-1135OC', 'https://pubmed.ncbi.nlm.nih.gov/40126143/', NULL, '["quality"]', 1, '["nick"]');
