INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('amagai-2025-icu-readmission-epidemiology', 'The Epidemiology of ICU Readmissions Across Ten Health Systems', 'Amagai S, Chaudhari V, Chhikara K, Ingraham NE, Hochberg CH, Barker AK, Mao C, Ortiz AC, Weissman GE, Schmid BE, Schwinne M, Bhavani SV, Guleria S, Liao Z, Markov N, Lyons PG, Park-Egan B, Parker WF, Luo Y, Rojas JC, Gao CA, Common Longitudinal ICU data Format (CLIF) Consortium.', 'Critical Care Explorations', 2025, 'Published', 'https://doi.org/10.1097/CCE.0000000000001341', 'https://pubmed.ncbi.nlm.nih.gov/41165278/', NULL, '["quality","clif"]', 0, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('thakkar-2025-llm-vs-traditional-ie', 'A Comparative Analysis of Large Language Models Versus Traditional Information Extraction Methods for Real-World Evidence of Patient Symptomatology in Acute and Post-Acute Sequelae of SARS-CoV-2', 'Thakkar V, Silverman GM, Kc A, Ingraham NE, Jones EK, King S, Melton GB, Zhang R, Tignanelli CJ.', 'PLoS One', 2025, 'Published', 'https://doi.org/10.1371/journal.pone.0323535', 'https://pubmed.ncbi.nlm.nih.gov/40373001/', NULL, '["quality"]', 0, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('mesfin-2025-loc-variation', 'Hospital and Temporal Variations in Limitations of Care Among Hospitalized Patients with COVID-19: A VIRUS Registry Retrospective Cohort Study', 'Mesfin N, Kumar Jain N, Khedr A, Mushtaq H, Jama AB, Attallah N, Hassan E, Langworthy B, Ingraham N, Garces JPD, Koritala T, Armaignac DL, Perkins NE, Belden K, Kumar V, Boman K, Sanghavi DK, Bansal V, Kashyap R, Cartin-Ceba R, Nou A, Walkey AJ, Dudley RA, Khan SA, Society of Critical Care Medicine Discovery Viral Infection and Respiratory Illness Universal Study (VIRUS): Covid-19 Registry Investigator Group.', 'Palliative Medicine Reports', 2025, 'Published', 'https://doi.org/10.1177/26892820251380523', 'https://pubmed.ncbi.nlm.nih.gov/41142473/', NULL, '["covid","decision-making"]', 0, '["nate","nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('gao-2025-clif-correspondence', 'Correspondence on "A Common Longitudinal Intensive Care Unit Data Format (CLIF) for Critical Illness Research". Author''s Reply', 'Gao CA, Ingraham NE, Hochberg CH, Weissman GE, Parker WF.', 'Intensive Care Medicine', 2025, 'Published', 'https://doi.org/10.1007/s00134-025-08029-2', 'https://pubmed.ncbi.nlm.nih.gov/40658245/', NULL, '["clif"]', 0, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('rojas-2025-clif-icm', 'A Common Longitudinal Intensive Care Unit Data Format (CLIF) for Critical Illness Research', 'Rojas JC, Lyons PG, Chhikara K, Chaudhari V, Bhavani SV, Nour M, Buell KG, Smith KD, Gao CA, Amagai S, Mao C, Luo Y, Barker AK, Nuppnau M, Hermsen M, Koyner JL, Beck H, Baccile R, Liao Z, Carey KA, Park-Egan B, Han X, Ortiz AC, Schmid BE, Weissman GE, Hochberg CH, Ingraham NE, Parker WF.', 'Intensive Care Medicine', 2025, 'Published', 'https://doi.org/10.1007/s00134-025-07848-7', 'https://pubmed.ncbi.nlm.nih.gov/40080116/', NULL, '["clif"]', 1, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('ingraham-2025-lpv-variation', 'Provider-Level Variation in Lung-Protective Ventilation Practices in the ICU', 'Ingraham NE, Collins C, Dudley RA, Chipman JG, Tignanelli CJ.', 'American Journal of Respiratory and Critical Care Medicine', 2025, 'In Review', NULL, NULL, 'Using multi-center CLIF data, this study quantifies the extent to which provider identity explains variation in lung-protective ventilation adherence beyond patient-level factors. We demonstrate substantial provider-level variation that persists after risk adjustment, suggesting targets for provider-focused quality improvement interventions.', '["ventilation","clif"]', 1, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('mesfin-2025-cci-ards', 'Chronic Critical Illness in ARDS: Incidence, Risk Factors, and Outcomes', 'Mesfin N, Ingraham NE, Eddington C, Bromley E, Tignanelli CJ.', 'CHEST', 2025, 'In Review', NULL, NULL, 'This study characterizes the incidence and risk factors for chronic critical illness (CCI) among patients with acute respiratory distress syndrome (ARDS) using multi-center ICU data. We identify distinct clinical trajectories and modifiable risk factors that may inform early intervention strategies.', '["clif"]', 0, '["nate","nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('byrd-2024-deterioration-definition', 'Beyond Unplanned ICU Transfers: Linking a Revised Definition of Deterioration to Patient Outcomes', 'Byrd TF, Phelan TA, Ingraham NE, Langworthy BW, Bhasin A, Kc A, Melton-Meaux GB, Tignanelli CJ.', 'Critical Care Medicine', 2024, 'Published', 'https://doi.org/10.1097/CCM.0000000000006333', 'https://pubmed.ncbi.nlm.nih.gov/38832836/', NULL, '["quality"]', 0, '["nick"]');
