INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('bramante-2024-metformin-viral-load', 'Favorable Antiviral Effect of Metformin on SARS-CoV-2 Viral Load in a Randomized, Placebo-Controlled Clinical Trial of COVID-19', 'Bramante CT, Beckman KB, Mehta T, Karger AB, Odde DJ, Tignanelli CJ, Buse JB, Johnson DM, Watson RHB, Daniel JJ, Liebovitz DM, Nicklas JM, Cohen K, Puskarich MA, Belani HK, Siegel LK, Klatt NR, Anderson B, Hartman KM, Rao V, Hagen AA, Patel B, Fenno SL, Avula N, Reddy NV, Erickson SM, Fricton RD, Lee S, Griffiths G, Pullen MF, Thompson JL, Sherwood NE, Murray TA, Rose MR, Boulware DR, Huling JD, COVID-OUT Study Team.', 'Clinical Infectious Diseases', 2024, 'Published', 'https://doi.org/10.1093/cid/ciae159', 'https://pubmed.ncbi.nlm.nih.gov/38690892/', NULL, '["covid"]', 0, '["nick"]');
