INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('boulware-2023-vaccination-severity', 'Impact of Severe Acute Respiratory Syndrome Coronavirus 2 (SARS-CoV-2) Vaccination and Booster on Coronavirus Disease 2019 (COVID-19) Symptom Severity Over Time in the COVID-OUT Trial', 'Boulware DR, Murray TA, Proper JL, Tignanelli CJ, Buse JB, Liebovitz DM, Nicklas JM, Cohen K, Puskarich MA, Belani HK, Siegel LK, Klatt NR, Odde DJ, Karger AB, Ingraham NE, Hartman KM, Rao V, Hagen AA, Patel B, Fenno SL, Avula N, Reddy NV, Erickson SM, Lindberg S, Fricton R, Lee S, Zaman A, Saveraid HG, Tordsen WJ, Pullen MF, Sherwood NE, Huling JD, Bramante CT, COVID-OUT study team.', 'Clinical Infectious Diseases', 2023, 'Published', 'https://doi.org/10.1093/cid/ciac772', 'https://pubmed.ncbi.nlm.nih.gov/36124697/', NULL, '["covid"]', 0, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('ikramuddin-2023-discharge-disposition', 'Predictors of Discharge Disposition and Mortality Following Hospitalization with SARS-CoV-2 Infection', 'Ikramuddin F, Melnik T, Ingraham NE, Nguyen N, Siegel L, Usher MG, Tignanelli CJ, Morse L.', 'PLoS One', 2023, 'Published', 'https://doi.org/10.1371/journal.pone.0283326', 'https://pubmed.ncbi.nlm.nih.gov/37053224/', NULL, '["covid"]', 0, '["nick"]');
