INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('kalinoski-2023-mrsa-pneumonia', 'Ventilator-Associated Methicillin-Resistant Staphylococcus aureus (MRSA) Pneumonia in a Patient with a Negative MRSA Nasal Swab', 'Kalinoski M, Ingraham NE.', 'American Journal of Case Reports', 2023, 'Published', 'https://doi.org/10.12659/AJCR.941088', 'https://pubmed.ncbi.nlm.nih.gov/37837186/', NULL, '["quality"]', 0, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('ingraham-2023-covid-out-longcovid', 'Outpatient Treatment of COVID-19 and Incidence of Post-COVID-19 Condition Over 10 Months (COVID-OUT): A Multicentre, Randomised, Quadruple-Blind, Parallel-Group, Phase 3 Trial', 'Bramante CT, Buse JB, Liebovitz DM, Nicklas JM, Puskarich MA, Cohen K, Belani HK, Anderson BJ, Huling JD, Tignanelli CJ, Thompson JL, Pullen M, Wirtz EL, Siegel LK, Proper JL, Odde DJ, Klatt NR, Sherwood NE, Lindberg SM, Karger AB, Beckman KB, Erickson SM, Fenno SL, Hartman KM, Rose MR, Mehta T, Patel B, Griffiths G, Bhat NS, Murray TA, Boulware DR, COVID-OUT Study Team.', 'The Lancet Infectious Diseases', 2023, 'Published', 'https://doi.org/10.1016/S1473-3099(23)00299-2', 'https://pubmed.ncbi.nlm.nih.gov/37302406/', 'In this pre-specified secondary analysis of the COVID-OUT randomized trial, we evaluated the effect of metformin, ivermectin, and fluvoxamine on the risk of developing Long COVID. Metformin was associated with a 41% reduction in Long COVID risk over 10 months of follow-up.', '["covid"]', 1, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('ingraham-2023-laps2-medcare', 'Prediction of In-Hospital Mortality Among Intensive Care Unit Patients Using Modified Daily Laboratory-Based Acute Physiology Score, Version 2', 'Kohn R, Weissman GE, Wang W, Ingraham NE, Scott S, Bayes B, Anesi GL, Halpern SD, Kipnis P, Liu VX, Dudley RA, Kerlin MP.', 'Medical Care', 2023, 'Published', 'https://doi.org/10.1097/MLR.0000000000001878', 'https://pubmed.ncbi.nlm.nih.gov/37308947/', NULL, '["quality"]', 0, '["nick"]');
