INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('bramante-2022-covid-out-nejm', 'Randomized Trial of Metformin, Ivermectin, and Fluvoxamine for Covid-19', 'Bramante CT, Huling JD, Tignanelli CJ, Buse JB, Liebovitz DM, Nicklas JM, Cohen K, Puskarich MA, Belani HK, Proper JL, Siegel LK, Klatt NR, Odde DJ, Luke DG, Anderson B, Karger AB, Ingraham NE, Hartman KM, Rao V, Hagen AA, Patel B, Fenno SL, Avula N, Reddy NV, Erickson SM, Lindberg S, Fricton R, Lee S, Zaman A, Saveraid HG, Tordsen WJ, Pullen MF, Biros M, Sherwood NE, Thompson JL, Boulware DR, Murray TA, COVID-OUT Trial Team.', 'New England Journal of Medicine', 2022, 'Published', 'https://doi.org/10.1056/NEJMoa2201662', 'https://pubmed.ncbi.nlm.nih.gov/36070710/', 'This phase 3, randomized, quadruple-blind trial (COVID-OUT) tested metformin, ivermectin, and fluvoxamine in non-hospitalized adults with COVID-19. Metformin reduced the risk of hypoxemia, emergency department visit, hospitalization, or death by 42% (OR 0.58; 95% CI 0.35-0.94).', '["covid"]', 1, '["nick"]');
