INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('ingraham-2022-disparities-covid', 'Racial and Ethnic Disparities in Hospital Admissions from COVID-19: Determining the Impact of Neighborhood Deprivation and Primary Language', 'Ingraham NE, Purcell LN, Karam BS, Dudley RA, Usher MG, Warlick CA, Allen ML, Melton GB, Charles A, Tignanelli CJ.', 'Journal of General Internal Medicine', 2022, 'Published', 'https://doi.org/10.1007/s11606-021-06790-w', 'https://pubmed.ncbi.nlm.nih.gov/34003427/', 'This study examines racial and ethnic disparities in COVID-19 hospital admissions and their relationship to neighborhood-level social determinants of health. Using geocoded data linked to area deprivation indices, we demonstrate how structural factors including neighborhood deprivation and primary language contribute to observed disparities.', '["covid","disparities"]', 0, '["nick"]');
INSERT INTO publications (id, title, authors, journal, year, status, doi, pubmed, abstract, topics, featured, author_slugs) VALUES ('bramante-2021-metformin-lancethl', 'Metformin and Risk of Mortality in Patients Hospitalised with COVID-19: A Retrospective Cohort Analysis', 'Bramante CT, Ingraham NE, Murray TA, Marmor S, Hovertsen S, Gronski J, McNeil C, Feng R, Guzman G, Abdelwahab N, King S, Tamariz L, Meehan T, Pendleton KM, Benson B, Vojta D, Tignanelli CJ.', 'Lancet Healthy Longevity', 2021, 'Published', 'https://doi.org/10.1016/S2666-7568(20)30033-7', 'https://pubmed.ncbi.nlm.nih.gov/33521772/', 'Retrospective cohort analysis of 6,256 adults hospitalized with COVID-19. Metformin use before hospitalization was associated with a significant reduction in in-hospital mortality (OR 0.52; 95% CI 0.37-0.73), providing observational rationale for the COVID-OUT randomized trial.', '["covid"]', 1, '["nick"]');
